# Exact normalized date and name anchors, ignoring volatile middle, gender, SSN, and location fields.
def date_name_anchors(r):
    import re
    import unicodedata
    import hashlib

    def norm(v):
        v = unicodedata.normalize("NFKD", str(v or ""))
        v = "".join(c for c in v if not unicodedata.combining(c)).lower()
        v = v.translate(str.maketrans({"0": "o", "1": "i", "3": "e", "5": "s"}))
        return re.sub(r"[^a-z0-9]+", "", v)

    def date_parts(v):
        raw = re.findall(r"\d+", str(v or ""))
        if not raw:
            return "", ""
        yi = next((i for i, x in enumerate(raw) if len(x) == 4), None)
        if yi is None:
            return "", ""
        year = raw[yi].zfill(4)
        others = [int(x) for i, x in enumerate(raw) if i != yi]
        full = ""
        if len(others) >= 2:
            a, b = sorted(others[:2])
            full = year + "-" + str(a) + "-" + str(b)
        return year, full

    def key(prefix, value):
        return prefix + hashlib.blake2b(value.encode(), digest_size=8).hexdigest()

    first, last = norm(r.get("first", "")), norm(r.get("last", ""))
    year, full_date = date_parts(r.get("birthdate", ""))
    out = []
    if full_date:
        out.append(key("d:", full_date))
    if first and last:
        out.append(key("n:", "|".join(sorted((first, last)))))
    if first and year:
        out.append(key("fy:", first + "|" + year))
    if last and year:
        out.append(key("ly:", last + "|" + year))
    return list(dict.fromkeys(out))


# Stable context anchors normalize addresses, exact identifiers, and year-qualified locality.
def context_anchors(r):
    import re
    import unicodedata
    import hashlib

    def words(v):
        v = unicodedata.normalize("NFKD", str(v or ""))
        v = "".join(c for c in v if not unicodedata.combining(c)).lower()
        v = v.translate(str.maketrans({"0": "o", "1": "i", "3": "e", "5": "s"}))
        return re.findall(r"[a-z0-9]+", v)

    def year_of(v):
        nums = re.findall(r"\d+", str(v or ""))
        return next((x.zfill(4) for x in nums if len(x) == 4), "")

    def zip_norm(v):
        z = "".join(words(v))
        if z.isdigit():
            return str(int(z)) if z else ""
        return z

    def address_base(v):
        toks = words(v)
        stop = {"apt", "apartment", "suite", "ste", "unit", "block", "dept"}
        cut = next((i for i, t in enumerate(toks) if t in stop), len(toks))
        toks = toks[:cut]
        aliases = {
            "street": "st", "str": "st", "avenue": "ave", "road": "rd",
            "boulevard": "blvd", "lane": "ln", "trail": "trl",
            "terrace": "ter", "court": "ct", "drive": "dr"
        }
        return "".join(aliases.get(t, t) for t in toks)

    def key(prefix, value):
        return prefix + hashlib.blake2b(value.encode(), digest_size=8).hexdigest()

    out = []
    address = address_base(r.get("address", ""))
    if address:
        out.append(key("a:", address))
    ssn = "".join(words(r.get("ssn", "")))
    if len(ssn) >= 4:
        out.append(key("s:", ssn))
    city = "".join(words(r.get("city", "")))
    zipcode = zip_norm(r.get("zip", ""))
    year = year_of(r.get("birthdate", ""))
    if city and zipcode and year:
        out.append(key("cyz:", city + "|" + zipcode + "|" + year))
    return list(dict.fromkeys(out))


# Compound-name token anchors tolerate reordered, added, omitted, or truncated name components and year-only dates.
def compound_name_anchors(r):
    import re
    import unicodedata
    import hashlib

    def tokens(v):
        v = unicodedata.normalize("NFKD", str(v or ""))
        v = "".join(c for c in v if not unicodedata.combining(c)).lower()
        v = v.translate(str.maketrans({"0": "o", "1": "i", "3": "e", "5": "s"}))
        return [x for x in re.findall(r"[a-z0-9]+", v) if x]

    def year_of(v):
        nums = re.findall(r"\d+", str(v or ""))
        return next((x.zfill(4) for x in nums if len(x) == 4), "")

    def zip_norm(v):
        z = "".join(tokens(v))
        if z.isdigit():
            return str(int(z)) if z else ""
        return z

    def key(prefix, value):
        return prefix + hashlib.blake2b(value.encode(), digest_size=8).hexdigest()

    first_tokens = tokens(r.get("first", ""))
    last_tokens = tokens(r.get("last", ""))
    all_tokens = list(dict.fromkeys(first_tokens + last_tokens))
    year = year_of(r.get("birthdate", ""))
    zipcode = zip_norm(r.get("zip", ""))
    out = []
    if year:
        for token in all_tokens:
            out.append(key("ty:", token + "|" + year))
    if zipcode:
        for token in all_tokens:
            out.append(key("tz:", token + "|" + zipcode))
    for f in first_tokens:
        for last in last_tokens:
            out.append(key("fl:", "|".join(sorted((f, last)))))
    return list(dict.fromkeys(out))


# Character-deletion signatures tolerate accents, punctuation, digit confusions, insertions, substitutions, and transpositions.
def fuzzy_name_signatures(r):
    import re
    import unicodedata
    import hashlib

    def tokens(v):
        v = unicodedata.normalize("NFKD", str(v or ""))
        v = "".join(c for c in v if not unicodedata.combining(c)).lower()
        v = v.translate(str.maketrans({
            "0": "o", "1": "i", "2": "z", "3": "e",
            "4": "a", "5": "s", "6": "g", "8": "b", "9": "g"
        }))
        return [x for x in re.findall(r"[a-z0-9]+", v) if x]

    def variants(s):
        vals = {s}
        if len(s) > 1:
            vals.update(s[:i] + s[i + 1:] for i in range(len(s)))
        return vals

    def year_of(v):
        nums = re.findall(r"\d+", str(v or ""))
        return next((x.zfill(4) for x in nums if len(x) == 4), "")

    def key(prefix, value):
        return prefix + hashlib.blake2b(value.encode(), digest_size=8).hexdigest()

    first_tokens = tokens(r.get("first", ""))
    last_tokens = tokens(r.get("last", ""))
    year = year_of(r.get("birthdate", ""))
    out = []
    if year:
        for token in set(first_tokens + last_tokens):
            for variant in variants(token):
                out.append(key("dy:", variant + "|" + year))
    for first in first_tokens:
        for last in last_tokens:
            for variant in variants(first):
                out.append(key("df:", variant + "|" + last))
            for variant in variants(last):
                out.append(key("dl:", first + "|" + variant))
    return list(dict.fromkeys(out))


SCHEMES = {
    "date_name_anchors": date_name_anchors,
    "context_anchors": context_anchors,
    "compound_name_anchors": compound_name_anchors,
    "fuzzy_name_signatures": fuzzy_name_signatures,
}
